//! RC-001 ITERATION 9 / V3 - media continuity of the repaired Return splice.
//!
//! The strict-contract tests prove the control flow with a synthetic stream.
//! This test proves the MEDIA: a real, decodable MPEG-TS (video + audio,
//! generated by ffmpeg) is pushed through the live engine, the TV performs a
//! washed-out Return at a saved bookmark, and the bytes served after the
//! re-anchor must still be a decodable MPEG-TS with both elementary streams,
//! PAT/PMT and monotonic video PTS.
//!
//! Host-only: no port, no provider, no production file, no USB/gadget command.
//! Skips cleanly when ffmpeg/ffprobe are unavailable.
//!
//! The live band is ~134 MiB into the source, and the returned-to bookmark is
//! washed out by the 128 MiB ring - the same shape as the physical incident
//! (`stale_bookmark_after_return_cold_reanchors_fresh_live`), but with a real
//! transport stream instead of the synthetic strict stream.

use std::fs;
use std::process::Command;
use std::sync::Arc;

use fuse_ntfs::contract::{StreamBackend, TS_PKT_SZ};
use fuse_ntfs::engine::live_engine::LiveEngine;
use fuse_ntfs::engine::ts_xform::SPLICE_PTS_EPS;

const MI: u64 = 1024 * 1024;
const BLOCK: usize = 65_536;
const PID_PAT: u16 = 0x0000;
const PID_PMT: u16 = 0x1000;

fn tool_ok(name: &str, arg: &str) -> bool {
    Command::new(name)
        .arg(arg)
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

fn have_ffmpeg() -> bool {
    tool_ok("ffmpeg", "-version") && tool_ok("ffprobe", "-version")
}

/// 300 s of MPEG-2 video + MP2 audio at a forced 4 Mbit/s CBR mux (~150 MB):
/// large enough to overflow the 128 MiB ring, so the bookmark really is washed
/// out and the re-anchor lands on the live band inside the real stream.
fn generate_ts(path: &str) {
    let status = Command::new("ffmpeg")
        .args([
            "-hide_banner",
            "-loglevel",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            "testsrc=size=320x240:rate=25:duration=300",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=1000:sample_rate=48000:duration=300",
            "-c:v",
            "mpeg2video",
            "-b:v",
            "3500k",
            "-c:a",
            "mp2",
            "-b:a",
            "192k",
            "-bf",
            "0",
            "-muxrate",
            "4000k",
            "-f",
            "mpegts",
            path,
        ])
        .status()
        .expect("spawn ffmpeg");
    assert!(status.success(), "ffmpeg failed to generate the source TS");
}

fn ts_pid(pkt: &[u8]) -> u16 {
    (((pkt[1] & 0x1F) as u16) << 8) | pkt[2] as u16
}

/// True when every 188-byte packet is a TS NULL packet (PID 0x1FFF).
fn all_null(buf: &[u8]) -> bool {
    match phase_of(buf) {
        Some(o) => buf[o..]
            .chunks_exact(TS_PKT_SZ)
            .all(|p| p[0] == 0x47 && ts_pid(p) == 0x1FFF),
        None => false,
    }
}

/// 188-byte packet phase of a served buffer, if any.
fn phase_of(buf: &[u8]) -> Option<usize> {
    if buf.len() < 3 * TS_PKT_SZ {
        return None;
    }
    (0..TS_PKT_SZ).find(|&o| {
        o + 3 * TS_PKT_SZ <= buf.len()
            && buf[o] == 0x47
            && buf[o + TS_PKT_SZ] == 0x47
            && buf[o + 2 * TS_PKT_SZ] == 0x47
    })
}

/// PES payload offset for a PUSI packet, if it carries a payload.
fn payload_off(p: &[u8]) -> Option<usize> {
    if p.len() < TS_PKT_SZ || p[0] != 0x47 || (p[1] & 0x40) == 0 {
        return None;
    }
    match (p[3] >> 4) & 0x3 {
        0b01 => Some(4),
        0b11 => {
            let afl = p[4] as usize;
            if 5 + afl < TS_PKT_SZ {
                Some(5 + afl)
            } else {
                None
            }
        }
        _ => None,
    }
}

fn read_ts_u64(b: &[u8]) -> u64 {
    (((b[0] >> 1) & 0x07) as u64) << 30
        | ((b[1] as u64) << 22)
        | (((b[2] >> 1) & 0x7F) as u64) << 15
        | ((b[3] as u64) << 7)
        | ((b[4] >> 1) & 0x7F) as u64
}

/// First/last PES timestamp for a stream-id class (`0xE0` video, `0xC0` audio).
fn pes_ts(buf: &[u8], last: bool, stream: u8, want_dts: bool) -> Option<u64> {
    let o = phase_of(buf)?;
    let mut found = None;
    for p in buf[o..].chunks_exact(TS_PKT_SZ) {
        let Some(po) = payload_off(p) else { continue };
        let pl = &p[po..];
        if pl.len() < 19 || pl[0] != 0 || pl[1] != 0 || pl[2] != 1 {
            continue;
        }
        let class_ok = match stream {
            0xE0 => pl[3] & 0xF0 == 0xE0,
            0xC0 => pl[3] & 0xE0 == 0xC0,
            _ => false,
        };
        if !class_ok {
            continue;
        }
        let v = if want_dts {
            if pl[7] & 0x40 == 0 {
                continue;
            }
            read_ts_u64(&pl[14..19])
        } else {
            if pl[7] & 0x80 == 0 {
                continue;
            }
            read_ts_u64(&pl[9..14])
        };
        found = Some(v);
        if !last {
            break;
        }
    }
    found
}

fn video_pts(buf: &[u8], last: bool) -> Option<u64> {
    pes_ts(buf, last, 0xE0, false)
}

fn audio_pts(buf: &[u8], last: bool) -> Option<u64> {
    pes_ts(buf, last, 0xC0, false)
}

fn video_dts(buf: &[u8], last: bool) -> Option<u64> {
    pes_ts(buf, last, 0xE0, true)
}

/// First/last PCR base (27 MHz) in a served buffer.
fn pcr_of(buf: &[u8], last: bool) -> Option<u64> {
    let o = phase_of(buf)?;
    let mut found = None;
    for p in buf[o..].chunks_exact(TS_PKT_SZ) {
        if p[0] != 0x47 {
            continue;
        }
        let afc = (p[3] >> 4) & 0x3;
        if afc & 0x2 == 0 {
            continue;
        }
        let afl = p[4] as usize;
        if afl < 7 || p[5] & 0x10 == 0 {
            continue;
        }
        found = Some(
            ((p[6] as u64) << 25)
                | ((p[7] as u64) << 17)
                | ((p[8] as u64) << 9)
                | ((p[9] as u64) << 1)
                | ((p[10] as u64) >> 7),
        );
        if !last {
            break;
        }
    }
    found
}

const TS_MOD: u64 = 1u64 << 33;

/// Wrap-aware forward delta between two 33-bit timestamps.
fn fwd_delta(a: u64, b: u64) -> i64 {
    let d = (b % TS_MOD + TS_MOD - a % TS_MOD) % TS_MOD;
    if d > TS_MOD / 2 {
        d as i64 - TS_MOD as i64
    } else {
        d as i64
    }
}

fn count_pid(buf: &[u8], pid: u16) -> usize {
    buf.chunks_exact(TS_PKT_SZ)
        .filter(|p| p[0] == 0x47 && ts_pid(p) == pid)
        .count()
}

/// Slices `buf` to the first 188-byte packet boundary (the engine may serve
/// from a packet phase offset), keeping whole packets only.
fn align_ts(buf: &[u8]) -> &[u8] {
    if buf.len() < 3 * TS_PKT_SZ {
        return buf;
    }
    for i in 0..=(buf.len() - 3 * TS_PKT_SZ) {
        if buf[i] == 0x47 && buf[i + TS_PKT_SZ] == 0x47 && buf[i + 2 * TS_PKT_SZ] == 0x47 {
            let len = ((buf.len() - i) / TS_PKT_SZ) * TS_PKT_SZ;
            return &buf[i..i + len];
        }
    }
    panic!("no 188-byte TS alignment found in the served media");
}

#[test]
fn return_splice_delivers_decodable_mpegts() {
    // A silent skip would let this regression gate "pass" without ever
    // exercising a decoder, which is exactly the evidence the audit needs.
    // Skipping is therefore an explicit opt-out only.
    if !have_ffmpeg() {
        assert_eq!(
            std::env::var("RC001_ALLOW_MEDIA_SKIP").as_deref(),
            Ok("1"),
            "[V3] ffmpeg/ffprobe missing: media continuity cannot be proven \
             (set RC001_ALLOW_MEDIA_SKIP=1 to opt out explicitly)"
        );
        eprintln!("[V3] ffmpeg/ffprobe unavailable - explicitly skipped via RC001_ALLOW_MEDIA_SKIP=1");
        return;
    }
    eprintln!("[V3] ffmpeg/ffprobe present: running real decode + probe");

    let dir = std::env::temp_dir().join("rc001_v3_media");
    fs::create_dir_all(&dir).expect("temp dir");
    let src = dir.join("live.ts");
    let out = dir.join("return.ts");

    if !src.exists() {
        generate_ts(src.to_str().expect("utf-8 path"));
    }
    let media = fs::read(&src).expect("read source TS");
    assert!(
        media.len() as u64 > 140 * MI,
        "source must overflow the 128 MiB ring: {} bytes",
        media.len()
    );

    let engine = Arc::new(LiveEngine::new());
    engine.ring.write_chunk(&media);

    // Cold open (anchors ~2 MiB into the stream) and play to 9 MiB, exactly as
    // the strict-contract tests do.
    let mut buf = vec![0u8; BLOCK];
    assert_eq!(engine.serve_live(0, 0, &mut buf, 1000), BLOCK);
    let base0 = engine.anchor.lock().unwrap().base_spos;
    let epoch0 = engine.anchor.lock().unwrap().epoch_seq;
    let mut foff = BLOCK as u64;
    while foff < 9 * MI {
        assert_eq!(engine.serve_live(0, foff, &mut buf, 1000), BLOCK);
        assert!(
            buf.iter().any(|b| *b == 0x47),
            "playback delivers a TS at {foff}"
        );
        foff += BLOCK as u64;
    }
    let cursor = engine.anchor.lock().unwrap().last_fend;
    assert!(cursor >= 9 * MI);

    // Timestamps of the last block delivered BEFORE the Return: the seam
    // reference for the post-splice continuity check.
    let pre_video_pts = video_pts(&buf, true);
    let pre_audio_pts = audio_pts(&buf, true);
    let pre_video_dts = video_dts(&buf, true);
    let pre_pcr = pcr_of(&buf, true);

    // Extend with a SECOND real segment: the ring keeps only 128 MiB, so this
    // washes the playback region out while the live band
    // (`s_write - LEADBACK`) stays inside decodable media.
    engine.ring.write_chunk(&media);

    let ring_old = engine.ring.lock().ring_old();
    let s_write = engine.ring.lock().s_write();
    let bookmark = 8 * MI + TS_PKT_SZ as u64;
    assert!(
        base0 + bookmark < ring_old,
        "the bookmark is washed out (mapped {}, ring_old {ring_old})",
        base0 + bookmark
    );
    assert!(s_write > ring_old, "the ring overflowed");

    // 2 h idle -> the player resumes at its saved bookmark.
    engine
        .ring
        .lock()
        .shift_time_back(std::time::Duration::from_secs(7200));

    // Read 1: washed out head, NULL-filled, no splice.
    assert_eq!(engine.serve_live(0, bookmark, &mut buf, 1000), BLOCK);
    assert!(
        all_null(&buf),
        "the washed-out head must be TS NULL packets only"
    );
    assert_eq!(engine.anchor.lock().unwrap().epoch_seq, epoch0);

    // Read 2: the repaired resume re-anchors to the live band with real media.
    assert_eq!(
        engine.serve_live(0, bookmark + BLOCK as u64, &mut buf, 1000),
        BLOCK
    );
    assert!(!all_null(&buf), "the live band delivers real media");
    assert_eq!(
        engine.anchor.lock().unwrap().epoch_seq,
        epoch0 + 1,
        "exactly one re-anchor"
    );

    // Capture from the ACTUAL splice block onward (Astra: the seam delivery
    // itself must be part of the evidence), ~2 MiB (~4 s at 4 Mbit/s).
    let mut captured: Vec<u8> = Vec::with_capacity(2 * MI as usize);
    captured.extend_from_slice(&buf);
    let mut f = bookmark + 2 * BLOCK as u64;
    while (captured.len() as u64) < 2 * MI {
        let n = engine.serve_live(0, f, &mut buf, 1000);
        assert_eq!(n, BLOCK, "live-band read at {f}");
        captured.extend_from_slice(&buf);
        f += BLOCK as u64;
    }
    let aligned = align_ts(&captured);
    fs::write(&out, aligned).expect("write captured TS");
    let captured = aligned;

    // ---- PAT / PMT present in the served media.
    assert!(count_pid(captured, PID_PAT) > 0, "served media carries PAT");
    assert!(count_pid(captured, PID_PMT) > 0, "served media carries PMT");

    // ---- seam continuity: last pre-Return timestamps vs the first timestamps
    // of the actual splice delivery (wrap-aware deltas). The PCR base is in
    // 90 kHz units (the 9-bit 27 MHz extension is not folded in).
    let post_video_pts = video_pts(captured, false);
    let post_audio_pts = audio_pts(captured, false);
    let post_video_dts = video_dts(captured, false);
    let post_pcr = pcr_of(captured, false);
    let d_pts = match (pre_video_pts, post_video_pts) {
        (Some(a), Some(b)) => fwd_delta(a, b),
        _ => panic!(
            "video PTS missing across the seam: pre={pre_video_pts:?} post={post_video_pts:?}"
        ),
    };
    let d_audio = match (pre_audio_pts, post_audio_pts) {
        (Some(a), Some(b)) => fwd_delta(a, b),
        _ => panic!(
            "audio PTS missing across the seam: pre={pre_audio_pts:?} post={post_audio_pts:?}"
        ),
    };
    let d_pcr = match (pre_pcr, post_pcr) {
        (Some(a), Some(b)) => fwd_delta(a, b),
        _ => panic!("PCR missing across the seam: pre={pre_pcr:?} post={post_pcr:?}"),
    };
    let d_dts = match (pre_video_dts, post_video_dts) {
        (Some(a), Some(b)) => Some(fwd_delta(a, b)),
        (None, None) => None,
        (a, b) => panic!("DTS present on only one side of the seam: pre={a:?} post={b:?}"),
    };
    eprintln!(
        "[V3] seam: video PTS {pre_video_pts:?} -> {post_video_pts:?} (delta {d_pts} @90kHz); \
         audio PTS delta {d_audio}; video DTS delta {d_dts:?}; \
         PCR base {pre_pcr:?} -> {post_pcr:?} (delta {d_pcr} @90kHz)"
    );

    // The fixture's reference splice must land exactly on ref + SPLICE_PTS_EPS.
    assert_eq!(
        d_pts, SPLICE_PTS_EPS as i64,
        "video PTS must continue exactly at ref + SPLICE_PTS_EPS"
    );
    // No PCR regression and no gap beyond one 25-fps frame (40 ms = 3600 ticks).
    assert!(
        (0..=3_600).contains(&d_pcr),
        "PCR base must not regress and must stay within one frame: {d_pcr} ticks @90kHz"
    );
    // Audio: no regression, and the gap is bounded by the mp2 PES interleave
    // granularity (1152-sample frames = 24 ms at 48 kHz; ffmpeg packs up to
    // ~5 frames per PES => 120 ms = 10_800 ticks). This is the spacing between
    // the last audio PES before the seam and the first after it, not a
    // discontinuity on the audio timeline.
    assert!(
        (0..=10_800).contains(&d_audio),
        "audio PTS must not regress and must stay within the mp2 PES granularity: {d_audio} ticks"
    );
    if let Some(d_dts) = d_dts {
        assert!(
            (0..=3_600).contains(&d_dts),
            "video DTS continuity across the seam: {d_dts} ticks @90kHz"
        );
    }

    // ---- ffprobe sees both elementary streams.
    let probe = Command::new("ffprobe")
        .args([
            "-v",
            "error",
            "-show_entries",
            "stream=codec_type",
            "-of",
            "csv=p=0",
            out.to_str().unwrap(),
        ])
        .output()
        .expect("ffprobe");
    assert!(probe.status.success(), "ffprobe failed: {:?}", probe.stderr);
    let kinds = String::from_utf8_lossy(&probe.stdout).to_lowercase();
    assert!(kinds.contains("video"), "served media has a video stream");
    assert!(kinds.contains("audio"), "served media has an audio stream");

    // ---- the whole captured slice decodes (video + audio) without fatal error.
    let decode = Command::new("ffmpeg")
        .args([
            "-hide_banner",
            "-v",
            "error",
            "-i",
            out.to_str().unwrap(),
            "-f",
            "null",
            "-",
        ])
        .output()
        .expect("ffmpeg decode");
    let stderr = String::from_utf8_lossy(&decode.stderr);
    assert!(
        decode.status.success(),
        "ffmpeg could not decode the served slice: {stderr}"
    );
    for bad in ["Invalid data found", "non-existing PPS", "error while decoding"] {
        assert!(!stderr.contains(bad), "decoder error `{bad}`: {stderr}");
    }

    // ---- video PTS is monotonic across the served window.
    let pk = Command::new("ffprobe")
        .args([
            "-v",
            "error",
            "-select_streams",
            "v:0",
            "-show_entries",
            "packet=pts_time",
            "-of",
            "csv=p=0",
            out.to_str().unwrap(),
        ])
        .output()
        .expect("ffprobe pts");
    assert!(pk.status.success());
    let pts: Vec<f64> = String::from_utf8_lossy(&pk.stdout)
        .lines()
        .filter_map(|l| l.trim().trim_end_matches(',').parse::<f64>().ok())
        .collect();
    assert!(pts.len() > 20, "enough video packets: {}", pts.len());
    for w in pts.windows(2) {
        assert!(
            w[1] >= w[0],
            "video PTS regressed across the served window: {} -> {}",
            w[0],
            w[1]
        );
    }
    eprintln!(
        "[V3] served {} bytes after the Return: PAT={} PMT={} video_packets={} pts {:.3}..{:.3}",
        captured.len(),
        count_pid(&captured, PID_PAT),
        count_pid(&captured, PID_PMT),
        pts.len(),
        pts.first().copied().unwrap_or(0.0),
        pts.last().copied().unwrap_or(0.0)
    );
}
